function f(n,e){return e<=8?Array.from({length:e},(o,t)=>t+1):[...new Set([1,e,n,n-1,n+1])].filter(o=>o>=1&&o<=e).sort((o,t)=>o-t)}function u(n,e,a,o){const t=n.filter(Boolean);if(a<=1){t.forEach(r=>{r.innerHTML=""});return}let c="",i=0;f(e,a).forEach(r=>{r-i>1&&(c+='<span class="pagina-reticencias">…</span>'),c+=`<button type="button" class="pagina-botao${r===e?" pagina-botao--ativo":""}"
            data-pagina="${r}"${r===e?' aria-current="page"':""}>${r}</button>`,i=r}),t.forEach(r=>{r.innerHTML=c,r.querySelectorAll("[data-pagina]").forEach(s=>{s.addEventListener("click",()=>o(Number(s.dataset.pagina)))})})}export{u as r};
